#include "pattern_stream_project.h"
#include <string.h>
typedef struct {fm1_stream_read_fn read;void *ctx;uint32_t length,at,decoded,pos,distance,left,first,have;uint8_t kind,value,cache[128],window[1024];} stream;
static uint32_t get32(const uint8_t *p){return (uint32_t)p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24;}
static uint32_t crc_byte(uint32_t c,uint8_t b){unsigned i;c^=b;for(i=0;i<8;i++)c=(c>>1)^(0xedb88320u&(0u-(c&1u)));return c;}
static int byte(stream *s,uint8_t *out){uint32_t n;if(s->at>=s->length)return -1;if(s->at<s->first||s->at-s->first>=s->have){s->first=s->at;n=s->length-s->at;if(n>sizeof s->cache)n=sizeof s->cache;if(s->read(s->ctx,s->at,s->cache,n))return -1;s->have=n;}*out=s->cache[s->at++-s->first];return 0;}
static int next(stream *s,uint8_t *out){uint8_t token,lo,hi,b;if(s->pos>=s->decoded)return -1;if(!s->left){if(byte(s,&token))return -1;s->kind=token>>6;s->left=(token&63u)+1u;if(s->left>s->decoded-s->pos)return -1;if(s->kind==0&&s->left>s->length-s->at)return -1;if(s->kind==2&&byte(s,&s->value))return -1;if(s->kind==3){if(byte(s,&lo)||byte(s,&hi))return -1;s->distance=(uint32_t)lo|(uint32_t)hi<<8;if(!s->distance||s->distance>sizeof s->window||s->distance>s->pos)return -1;}}if(s->kind==0){if(byte(s,&b))return -1;}else b=s->kind==1?0:s->kind==2?s->value:s->window[(s->pos-s->distance)%sizeof s->window];s->window[s->pos%sizeof s->window]=b;s->pos++;s->left--;*out=b;return 0;}
static int decoded_read(void *v,uint32_t offset,void *dst,uint32_t n){stream *s=v;uint8_t b,*out=dst;uint32_t i;if((!dst&&n)||offset>s->decoded||n>s->decoded-offset)return -1;if(offset<s->pos){s->pos=0;s->at=12;s->left=0;}while(s->pos<offset)if(next(s,&b))return -1;for(i=0;i<n;i++){if(next(s,&b))return -1;out[i]=b;}return 0;}
int fm1_stream_project_decode(fm1_stream_read_fn read,void *ctx,uint32_t length,fm1_project_session_valid valid,void *vctx,fm1_project_work *work,uint8_t *session,br_pattern_bank *bank,uint8_t *arena,size_t capacity,br_pattern_snapshot *live,fm1_pattern_song *song){stream s;uint8_t h[12],b;uint32_t crc=~0u,i;if(!read||length<12||length>3584u||read(ctx,0,h,sizeof h)||memcmp(h,"PSC\3",4))return FM1_PROJECT_INVALID;memset(&s,0,sizeof s);s.read=read;s.ctx=ctx;s.length=length;s.decoded=get32(h+4);s.at=12;if(s.decoded<FM1_PROJECT_HEADER_BYTES+FM1_PROJECT_SESSION||s.decoded>FM1_PROJECT_MAX)return FM1_PROJECT_INVALID;for(i=0;i<s.decoded;i++){if(next(&s,&b))return FM1_PROJECT_INVALID;crc=crc_byte(crc,b);}if(s.left||s.at!=length||~crc!=get32(h+8))return FM1_PROJECT_INVALID;s.pos=0;s.at=12;s.left=0;return fm1_project_decode_stream(decoded_read,&s,s.decoded,valid,vctx,work,session,bank,arena,capacity,live,song);}
